def findDisappearedNumbers(nums: list[int]) -> list[int]:
    for num in nums:
        idx = abs(num) - 1
        if nums[idx] > 0:
            nums[idx] = -nums[idx]

    return [i + 1 for i in range(len(nums)) if nums[i] > 0]

